import{_ as i,o as a,c as e,ak as r}from"./chunks/framework.DvrM7GBU.js";const b=JSON.parse('{"title":"知识标签体系总表","description":"","frontmatter":{},"headers":[],"relativePath":"元信息/知识标签体系总表.md","filePath":"元信息/知识标签体系总表.md","lastUpdated":1777893104000}'),h={name:"元信息/知识标签体系总表.md"};function d(n,l,o,c,t,_){return a(),e("div",null,[...l[0]||(l[0]=[r('<h1 id="知识标签体系总表" tabindex="-1">知识标签体系总表 <a class="header-anchor" href="#知识标签体系总表" aria-label="Permalink to “知识标签体系总表”">​</a></h1><ul><li>分类：维护规范</li><li>子系统：知识库工程 / 标签体系 / 检索结构</li><li>关键词标签：标签体系, 分类体系, 检索标签, 教程, 脚本, 引擎更新, OCR, UI, 广播, 战斗系统</li><li>来源类型：现有知识库结构交叉整理</li><li>证据等级：知识库内部规范</li><li>完整度状态：持续扩展中</li><li>来源文件：<code>docs/知识库总索引.md</code>; <code>docs/元信息/知识条目统一元数据规范.md</code></li><li>最后更新：2026-04-20</li><li>适合查询：标签怎么统一、某篇文档该打什么标签、怎么减少同义词混乱</li></ul><h2 id="_1-文档目的" tabindex="-1">1. 文档目的 <a class="header-anchor" href="#_1-文档目的" aria-label="Permalink to “1. 文档目的”">​</a></h2><p>本表用于给 <code>创游世界资料汇总</code> 知识库建立较统一的标签体系，方便后续：</p><ul><li>全局搜索</li><li>文档聚类</li><li>AI/RAG 切块检索</li><li>同主题自动归档</li><li>后续批量补索引</li></ul><p>原则上，标签不求一次性极多，而求：</p><ul><li>命名稳定</li><li>粒度适中</li><li>能长期复用</li><li>能覆盖主要研究方向</li></ul><hr><h2 id="_2-一级标签-文档类型" tabindex="-1">2. 一级标签：文档类型 <a class="header-anchor" href="#_2-一级标签-文档类型" aria-label="Permalink to “2. 一级标签：文档类型”">​</a></h2><h3 id="_2-1-教程类" tabindex="-1">2.1 教程类 <a class="header-anchor" href="#_2-1-教程类" aria-label="Permalink to “2.1 教程类”">​</a></h3><p>适用于官方教程、教程总结、学习路径、教程主题拆解。</p><p>推荐标签：</p><ul><li>教程</li><li>官方教程</li><li>学习路线</li><li>入门</li><li>进阶</li></ul><h3 id="_2-2-脚本类" tabindex="-1">2.2 脚本类 <a class="header-anchor" href="#_2-2-脚本类" aria-label="Permalink to “2.2 脚本类”">​</a></h3><p>适用于脚本界面、积木逻辑、作用域、组件能力、实战结构。</p><p>推荐标签：</p><ul><li>脚本</li><li>积木</li><li>作用域</li><li>数据流</li><li>组件体系</li><li>实战架构</li></ul><h3 id="_2-3-引擎更新类" tabindex="-1">2.3 引擎更新类 <a class="header-anchor" href="#_2-3-引擎更新类" aria-label="Permalink to “2.3 引擎更新类”">​</a></h3><p>适用于版本更新、能力变动、修复记录、兼容性说明。</p><p>推荐标签：</p><ul><li>版本更新</li><li>引擎更新</li><li>兼容性</li><li>调试</li><li>联机演进</li></ul><h3 id="_2-4-社区分析类" tabindex="-1">2.4 社区分析类 <a class="header-anchor" href="#_2-4-社区分析类" aria-label="Permalink to “2.4 社区分析类”">​</a></h3><p>适用于个人观察、逆向线索、推测研究、待验证结论。</p><p>推荐标签：</p><ul><li>社区分析</li><li>观察</li><li>推测</li><li>待验证</li><li>伪源码</li></ul><h3 id="_2-5-ocr-归档类" tabindex="-1">2.5 OCR 归档类 <a class="header-anchor" href="#_2-5-ocr-归档类" aria-label="Permalink to “2.5 OCR 归档类”">​</a></h3><p>适用于截图转文本、映射表、完整化工程、编号追踪。</p><p>推荐标签：</p><ul><li>OCR</li><li>截图转文本</li><li>映射表</li><li>证据追踪</li><li>完整化</li></ul><h3 id="_2-6-工程维护类" tabindex="-1">2.6 工程维护类 <a class="header-anchor" href="#_2-6-工程维护类" aria-label="Permalink to “2.6 工程维护类”">​</a></h3><p>适用于术语表、元数据规范、标签规范、状态总表、路线图。</p><p>推荐标签：</p><ul><li>维护规范</li><li>元数据</li><li>标签体系</li><li>状态管理</li><li>路线图</li></ul><hr><h2 id="_3-二级标签-对象与结构" tabindex="-1">3. 二级标签：对象与结构 <a class="header-anchor" href="#_3-二级标签-对象与结构" aria-label="Permalink to “3. 二级标签：对象与结构”">​</a></h2><h3 id="_3-1-素材相关" tabindex="-1">3.1 素材相关 <a class="header-anchor" href="#_3-1-素材相关" aria-label="Permalink to “3.1 素材相关”">​</a></h3><ul><li>素材</li><li>物体</li><li>实例化</li><li>原素材</li><li>贴图</li><li>文件夹</li></ul><h3 id="_3-2-组件相关" tabindex="-1">3.2 组件相关 <a class="header-anchor" href="#_3-2-组件相关" aria-label="Permalink to “3.2 组件相关”">​</a></h3><ul><li>组件</li><li>自定义组件</li><li>组件挂载</li><li>组件分类</li><li>属性</li><li>指令</li><li>触发时机</li></ul><h3 id="_3-3-数据相关" tabindex="-1">3.3 数据相关 <a class="header-anchor" href="#_3-3-数据相关" aria-label="Permalink to “3.3 数据相关”">​</a></h3><ul><li>数据类型</li><li>结构体</li><li>局部变量</li><li>自身属性</li><li>地图属性</li><li>系统属性</li><li>云变量</li><li>数据流</li></ul><hr><h2 id="_4-二级标签-界面与交互" tabindex="-1">4. 二级标签：界面与交互 <a class="header-anchor" href="#_4-二级标签-界面与交互" aria-label="Permalink to “4. 二级标签：界面与交互”">​</a></h2><h3 id="_4-1-ui-相关" tabindex="-1">4.1 UI 相关 <a class="header-anchor" href="#_4-1-ui-相关" aria-label="Permalink to “4.1 UI 相关”">​</a></h3><ul><li>UI</li><li>地图UI</li><li>操作UI</li><li>物体UI</li><li>当前UI</li><li>UI切换</li><li>UI同步</li></ul><h3 id="_4-2-交互相关" tabindex="-1">4.2 交互相关 <a class="header-anchor" href="#_4-2-交互相关" aria-label="Permalink to “4.2 交互相关”">​</a></h3><ul><li>广播</li><li>地图广播</li><li>交互</li><li>点击</li><li>输入</li><li>按钮</li><li>事件驱动</li></ul><hr><h2 id="_5-二级标签-玩法与系统" tabindex="-1">5. 二级标签：玩法与系统 <a class="header-anchor" href="#_5-二级标签-玩法与系统" aria-label="Permalink to “5. 二级标签：玩法与系统”">​</a></h2><h3 id="_5-1-战斗相关" tabindex="-1">5.1 战斗相关 <a class="header-anchor" href="#_5-1-战斗相关" aria-label="Permalink to “5.1 战斗相关”">​</a></h3><ul><li>战斗系统</li><li>生命</li><li>伤害</li><li>血条</li><li>子弹</li><li>近战武器</li><li>远程武器</li><li>Buff</li><li>动作状态</li></ul><h3 id="_5-2-经济与背包相关" tabindex="-1">5.2 经济与背包相关 <a class="header-anchor" href="#_5-2-经济与背包相关" aria-label="Permalink to “5.2 经济与背包相关”">​</a></h3><ul><li>背包系统</li><li>商店系统</li><li>货币</li><li>格子UI</li><li>道具</li><li>购买</li><li>使用</li><li>丢弃</li></ul><h3 id="_5-3-流程与地图相关" tabindex="-1">5.3 流程与地图相关 <a class="header-anchor" href="#_5-3-流程与地图相关" aria-label="Permalink to “5.3 流程与地图相关”">​</a></h3><ul><li>地图</li><li>切图</li><li>胜负流程</li><li>计时器</li><li>全局流程</li><li>任务系统</li><li>事件系统</li></ul><hr><h2 id="_6-二级标签-技术与版本" tabindex="-1">6. 二级标签：技术与版本 <a class="header-anchor" href="#_6-二级标签-技术与版本" aria-label="Permalink to “6. 二级标签：技术与版本”">​</a></h2><h3 id="_6-1-联机与同步" tabindex="-1">6.1 联机与同步 <a class="header-anchor" href="#_6-1-联机与同步" aria-label="Permalink to “6.1 联机与同步”">​</a></h3><ul><li>联机</li><li>本地逻辑</li><li>上传并等待</li><li>公共数据</li><li>同步</li></ul><h3 id="_6-2-音频与显示" tabindex="-1">6.2 音频与显示 <a class="header-anchor" href="#_6-2-音频与显示" aria-label="Permalink to “6.2 音频与显示”">​</a></h3><ul><li>音频</li><li>BGM</li><li>声音实例</li><li>粒子</li><li>显示</li><li>进度条</li></ul><h3 id="_6-3-调试与性能" tabindex="-1">6.3 调试与性能 <a class="header-anchor" href="#_6-3-调试与性能" aria-label="Permalink to “6.3 调试与性能”">​</a></h3><ul><li>调试</li><li>调用栈</li><li>Debug</li><li>节点树</li><li>性能统计</li></ul><hr><h2 id="_7-状态标签" tabindex="-1">7. 状态标签 <a class="header-anchor" href="#_7-状态标签" aria-label="Permalink to “7. 状态标签”">​</a></h2><p>用于表示文档成熟度与处理状态：</p><ul><li>草稿</li><li>已整理</li><li>深度整理</li><li>持续扩展中</li><li>近完整</li><li>待复核</li><li>待补证据</li><li>待补索引</li></ul><p>注意：</p><ul><li>“深度整理” 与 “持续扩展中” 可并存于不同维度理解，但文档头部建议主状态只保留一个最主要状态</li></ul><hr><h2 id="_8-证据标签" tabindex="-1">8. 证据标签 <a class="header-anchor" href="#_8-证据标签" aria-label="Permalink to “8. 证据标签”">​</a></h2><p>用于标注结论来源可靠度：</p><ul><li>官方说明</li><li>截图直接证据</li><li>多来源交叉归纳</li><li>社区推测</li><li>待验证</li></ul><hr><h2 id="_9-推荐打标签规则" tabindex="-1">9. 推荐打标签规则 <a class="header-anchor" href="#_9-推荐打标签规则" aria-label="Permalink to “9. 推荐打标签规则”">​</a></h2><h3 id="_9-1-单篇文档标签数量建议" tabindex="-1">9.1 单篇文档标签数量建议 <a class="header-anchor" href="#_9-1-单篇文档标签数量建议" aria-label="Permalink to “9.1 单篇文档标签数量建议”">​</a></h3><ul><li>主标签：1~2 个</li><li>次标签：3~6 个</li><li>不建议堆太多近义词</li></ul><h3 id="_9-2-命名优先级" tabindex="-1">9.2 命名优先级 <a class="header-anchor" href="#_9-2-命名优先级" aria-label="Permalink to “9.2 命名优先级”">​</a></h3><p>优先使用已经在知识库中稳定出现的表达，例如：</p><ul><li>用“系统属性”而不是“全局属性”混写</li><li>用“地图属性”而不是“场景属性”混写</li><li>用“当前UI”而不是多个自定义说法混写</li></ul><h3 id="_9-3-视频文档标签" tabindex="-1">9.3 视频文档标签 <a class="header-anchor" href="#_9-3-视频文档标签" aria-label="Permalink to “9.3 视频文档标签”">​</a></h3><p>视频文档建议同时打：</p><ul><li>内容标签</li><li>难度标签</li><li>实战标签</li></ul><p>例如：</p><ul><li>教程 / 脚本 / UI / 背包系统 / 入门 / 可复现</li></ul><hr><h2 id="_10-后续维护建议" tabindex="-1">10. 后续维护建议 <a class="header-anchor" href="#_10-后续维护建议" aria-label="Permalink to “10. 后续维护建议”">​</a></h2><ol><li>新增文档时优先从本表选标签，不轻易新增同义词</li><li>若确实需要新标签，应先判断是否能并入现有标签体系</li><li>后续可为高价值文档补“标签汇总区块”，提升检索一致性</li></ol><hr><h2 id="_11-关联阅读" tabindex="-1">11. 关联阅读 <a class="header-anchor" href="#_11-关联阅读" aria-label="Permalink to “11. 关联阅读”">​</a></h2><ul><li><code>docs/元信息/知识条目统一元数据规范.md</code></li><li><code>docs/元信息/创游世界术语表.md</code></li><li><code>docs/知识库总索引.md</code></li></ul>',91)])])}const u=i(h,[["render",d]]);export{b as __pageData,u as default};
